-- Deepholm: creature abilities
-- Most of the zone's creatures (the Twilight's Hammer, the earth elementals, the stone troggs and the crystal creatures) had no AI
-- or ran classic rows: port their abilities from the Cataclysm data, falling back to the classic data where Cataclysm has none,
-- keeping the quest scripts already in place; gossip and quest reward scripts of the references are left out. The creatures no
-- reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '43123';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

