SET @ENTRIES := '42470,42475,42521,42522,42524,42525,42606,42607,42711,42766,42779,42780,42792,42823,42824,42889,42914,42916,42917,42918,42921,42923,42924,43026,43031,43039,43101,43134,43158,43171,43174,43181,43218,43228,43232,43233,43234,43250,43339,43367,43368,43373,43388,43456,43480,43501,43513,43598,43616,43652,43847,43954,43966,43967,43971,43992,43995,44035,44038,44076,44131,44135,44148,44151,44152,44189,44220,44221,44257,44259,44289,44358,44363,44425,44619,44649,44680,44681,44683,44685,44686,44835,44847,44849,44855,44879,44936,44967,44988,44998,45084,47071,47072,47184,48533,49815,49816,49822,50059,50060,50061';

